package org.csu.mypetstore.user.controller;

import jakarta.servlet.http.HttpSession;import org.csu.mypetstore.user.domain.Views.CheckoutToken;import org.csu.mypetstore.user.security.StorePrincipal;import org.csu.mypetstore.user.service.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class OrderController {
    private static final String CHECKOUT="CHECKOUT_TOKEN";private final OrderService orders;public OrderController(OrderService o){orders=o;}
    @GetMapping("/checkout")String checkout(@AuthenticationPrincipal StorePrincipal user,HttpSession session,Model m,RedirectAttributes r){try{CheckoutToken token=orders.snapshot(user.id());session.setAttribute(CHECKOUT,token);var lines=orders.cart(user.id());m.addAttribute("lines",lines);m.addAttribute("total",orders.total(lines));return "Checkout";}catch(StoreException e){session.removeAttribute(CHECKOUT);r.addFlashAttribute("error",e.getMessage());return "redirect:/cart";}}
    @PostMapping("/orders")String create(@AuthenticationPrincipal StorePrincipal user,HttpSession session,@RequestParam String receiverName,@RequestParam String receiverPhone,@RequestParam String receiverAddress,RedirectAttributes r){try{long id=orders.create(user.id(),(CheckoutToken)session.getAttribute(CHECKOUT),receiverName,receiverPhone,receiverAddress);session.removeAttribute(CHECKOUT);r.addFlashAttribute("message","订单创建成功，请完成支付");return "redirect:/orders/"+id;}catch(StoreException e){r.addFlashAttribute("error",e.getMessage());return "redirect:/checkout";}}
    @GetMapping("/orders")String list(@AuthenticationPrincipal StorePrincipal user,@RequestParam(required=false)String status,@RequestParam(required=false)String orderNo,@RequestParam(defaultValue="1")long page,@RequestParam(defaultValue="10")long pageSize,Model m){m.addAttribute("page",orders.list(user.id(),status,orderNo,page,pageSize));m.addAttribute("status",status);m.addAttribute("orderNo",orderNo);m.addAttribute("pageSize",pageSize);return "ListOrders";}
    @GetMapping("/orders/{id}")String detail(@AuthenticationPrincipal StorePrincipal user,@PathVariable long id,Model m){var order=orders.get(user.id(),id);m.addAttribute("order",order);m.addAttribute("lines",orders.lines(id));return "ViewOrder";}
    @GetMapping("/orders/{id}/payment")String payment(@AuthenticationPrincipal StorePrincipal user,@PathVariable long id,Model m){var order=orders.get(user.id(),id);if(!"PENDING_PAYMENT".equals(order.getStatus()))throw new StoreException("当前订单无需支付");m.addAttribute("order",order);return "Payment";}
    @PostMapping("/orders/{id}/payment")String pay(@AuthenticationPrincipal StorePrincipal user,@PathVariable long id,@RequestParam String result,RedirectAttributes r){try{orders.pay(user.id(),id,"success".equals(result));r.addFlashAttribute("message","支付成功");r.addFlashAttribute("justPaid",true);}catch(StoreException e){r.addFlashAttribute("error",e.getMessage());}return "redirect:/orders/"+id;}
    @PostMapping("/orders/{id}/cancel")String cancel(@AuthenticationPrincipal StorePrincipal user,@PathVariable long id,@RequestParam(defaultValue="detail")String returnTo,RedirectAttributes r){try{orders.cancel(user.id(),id);r.addFlashAttribute("message","订单已取消，库存已恢复");}catch(StoreException e){r.addFlashAttribute("error",e.getMessage());}return "list".equals(returnTo)?"redirect:/orders":"redirect:/orders/"+id;}
    @PostMapping("/orders/{id}/complete")String complete(@AuthenticationPrincipal StorePrincipal user,@PathVariable long id,RedirectAttributes r){try{orders.complete(user.id(),id);r.addFlashAttribute("message","已确认收货");}catch(StoreException e){r.addFlashAttribute("error",e.getMessage());}return "redirect:/orders/"+id;}
}
